  ///		3、YYYY/MM/DD	例如2005/01/20
  ///		4、DD/MM/YYYY	例如20/01/2005
  ///		5、MM/DD/YYYY	例如01/20/2005
  ///		6、YYYYMM	    例如200501
  ///		7、YYYY年MM月 	例如2005年01月
  ///		8、YYYY年M月 	例如2005年1月
  ///		9、YYYY年MM月DD日	例如2005年01月20日
  ///		10、YYYY年M月D日	例如2005年1月20日
  /// </summary>
  /// <param name="strFormat">日期格式,0:8位日期,1:10位横杠日期,2:10位斜杠日期</param>
  /// <returns>返回:指定格式的日期串</returns>
  getDateStr_s(t) {
    let r, o, s;
    const n = this.year.toString().trim();
    switch (this.month > 9 ? o = this.month.toString().trim() : o = `0${this.month.toString().trim()}`, this.Day > 9 ? s = this.Day.toString().trim() : s = `0${this.Day.toString().trim()}`, r = n + o + s, t) {
      case "YYYYMMDD":
        r = n + o + s;
        break;
      case "YYYY-MM-DD":
        r = `${n}-${o}-${s}`;
        break;
      case "YYYY/MM/DD":
        r = `${n}/${o}/${s}`;
        break;
      case "DD/MM/YYYY":
        r = Format("{0}/{1}/{2}", s, o, n);
        break;
      case "MM/DD/YYYY":
        r = Format("{1}/{0}/{2}", s, o, n);
        break;
      case "YYYYMM":
        r = n + o;
        break;
      case "YYYY年MM月":
        r = `${n}年${o}月`;
        break;
      case "YYYY年M月":
        r = `${n}年${this.month.toString()}月`;
        break;
      case "YYYY年MM月DD日":
        r = `${n}年${o}月${s}日`;
        break;
      case "YYYY年M月D日":
        r = `${n}年${this.month.toString()}月${this.Day.toString()}日`;
        break;
    }
    return r;
  }
